draw:
(ctx, W, H) => {
  // Background
  ctx.fillStyle = '#06121f';
  ctx.fillRect(0, 0, W, H);
  // Gradient overlay
  const g = ctx.createRadialGradient(W/2, H*0.4, 0, W/2, H*0.4, Math.max(W, H)*0.7);
  g.addColorStop(0, 'rgba(56, 189, 248, 0.55)');
  g.addColorStop(1, 'rgba(56, 189, 248, 0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);
  // Particles
  ctx.globalCompositeOperation = 'screen';
  for (let i = 0; i < 220; i++) {
    const x = Math.random() * W;
    const y = Math.random() * H;
    const r = 1 + Math.random() * 3;
    const a = 0.3 + Math.random() * 0.6;
    ctx.fillStyle = `rgba(${100 + Math.random()*155}, ${180 + Math.random()*60}, 255, ${a})`;
    ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI*2); ctx.fill();
  }
  ctx.globalCompositeOperation = 'source-over';
  // Title
  ctx.fillStyle = '#f8fafc';
  ctx.font = 'bold 96px Georgia, serif';
  ctx.textAlign = 'center';
  ctx.fillText('Ocean Plastic', W/2, H*0.85);
  ctx.fillStyle = '#94a3b8';
  ctx.font = '32px Helvetica, Arial, sans-serif';
  ctx.fillText('A SHORT FILM', W/2, H*0.88 + 90);
}
